import java.sql.*;import java.util.*;public class StudentDAO{private Student row(ResultSet r)throws SQLException{return new Student(r.getInt("id"),r.getString("name"),r.getString("roll_no"),r.getString("department"),r.getString("email"),r.getString("phone"),r.getDouble("marks"));}public boolean add(Student s){String q="INSERT INTO students(name,roll_no,department,email,phone,marks)VALUES(?,?,?,?,?,?)";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,s.getName());p.setString(2,s.getRollNo());p.setString(3,s.getDepartment());p.setString(4,s.getEmail());p.setString(5,s.getPhone());p.setDouble(6,s.getMarks());return p.executeUpdate()>0;}catch(SQLException e){System.out.println("Add failed: "+e.getMessage());return false;}}public List<Student> all(){List<Student>l=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();ResultSet r=c.createStatement().executeQuery("SELECT * FROM students ORDER BY id")){while(r.next())l.add(row(r));}catch(SQLException e){System.out.println(e.getMessage());}return l;}public Student byRoll(String x){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM students WHERE roll_no=?")){p.setString(1,x);ResultSet r=p.executeQuery();if(r.next())return row(r);}catch(SQLException e){System.out.println(e.getMessage());}return null;}public List<Student> search(String col,String x){List<Student>l=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM students WHERE "+col+" LIKE ?")){p.setString(1,"%"+x+"%");ResultSet r=p.executeQuery();while(r.next())l.add(row(r));}catch(SQLException e){System.out.println(e.getMessage());}return l;}public List<Student> above(double m){List<Student>l=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM students WHERE marks>? ORDER BY marks DESC")){p.setDouble(1,m);ResultSet r=p.executeQuery();while(r.next())l.add(row(r));}catch(SQLException e){System.out.println(e.getMessage());}return l;}public boolean update(Student s){String q="UPDATE students SET name=?,roll_no=?,department=?,email=?,phone=?,marks=? WHERE id=?";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,s.getName());p.setString(2,s.getRollNo());p.setString(3,s.getDepartment());p.setString(4,s.getEmail());p.setString(5,s.getPhone());p.setDouble(6,s.getMarks());p.setInt(7,s.getId());return p.executeUpdate()>0;}catch(SQLException e){System.out.println(e.getMessage());return false;}}public boolean delete(int id){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM students WHERE id=?")){p.setInt(1,id);return p.executeUpdate()>0;}catch(SQLException e){System.out.println(e.getMessage());return false;}}public void stats(){try(Connection c=DatabaseConnection.getConnection();ResultSet r=c.createStatement().executeQuery("SELECT COUNT(*) c,MAX(marks) hi,MIN(marks) lo FROM students")){if(r.next())System.out.println("Total: "+r.getInt(1)+" | Highest: "+r.getDouble(2)+" | Lowest: "+r.getDouble(3));}catch(SQLException e){System.out.println(e.getMessage());}}}
